// ─────────────────────────────────────────────────────────────────────────────
// Commerce API — generated by Backplane for {{PROJECT_NAME}}
//
// Checkout → verified Stripe webhook → order in Supabase → signed, expiring
// R2 download link → email through Resend. Refunds revoke downloads.
//
// What's for sale lives in CATALOG (set by Backplane from the Products tab).
// Browsers send an item key and a quantity — never a price or an amount.
//
// Backplane tracks this file. If you change it, Backplane marks it
// USER MODIFIED and never overwrites it without asking.
// Configuration lives in wrangler.jsonc (vars) and Worker secrets.
// ─────────────────────────────────────────────────────────────────────────────

const STRIPE_VERSION = "2026-08-26.dahlia";
const JSON_HEADERS = { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" };
const REQUIRED = ["SUPABASE_URL", "SUPABASE_SECRET_KEY", "STRIPE_SECRET_KEY", "STRIPE_WEBHOOK_SECRET",
  "RESEND_API_KEY", "FROM_EMAIL", "DOWNLOAD_SIGNING_SECRET", "BACKPLANE_PROBE_TOKEN", "PRODUCT_NAME"];
// The Worker checks this many prices itself; Backplane checks every price directly.
const HEALTH_PRICE_LIMIT = 8;

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const origin = request.headers.get("Origin");
    try {
      if (request.method === "OPTIONS") return preflight(env, origin);
      const path = url.pathname.replace(/\/+$/, "") || "/";
      if (path === "/") return json({ service: env.WORKER_NAME || "commerce-api", ok: true });
      if (path === "/products" && request.method === "GET") return withCors(publicCatalog(env), env, origin);
      if (path === "/checkout" && (request.method === "POST" || request.method === "GET")) return withCors(await checkout(request, env, url), env, origin);
      if (path === "/thanks" && request.method === "GET") return await thanks(url, env);
      if (path === "/stripe/webhook" && request.method === "POST") return await stripeWebhook(request, env, ctx, url);
      if (path === "/download" && request.method === "GET") return await download(url, env, ctx);
      if (path === "/resend/webhook" && request.method === "POST") return await resendWebhook(request, env, ctx);
      if (path === "/license/validate" && request.method === "POST") return withCors(await validateLicense(request, env), env, origin);
      if (path === "/links" && request.method === "POST") return withCors(await resendLinks(request, env, ctx, url), env, origin);
      if (path === "/__backplane/health") return await health(request, env, url);
      if (path.startsWith("/__backplane/probe/stripe/")) return await probeStripe(request, env, path.split("/").pop());
      return json({ error: "not found" }, 404);
    } catch (err) {
      console.error("Unhandled error", request.method, url.pathname, err && err.stack || err);
      ctx.waitUntil(logEvent(env, "worker", "error", `${request.method} ${url.pathname} failed: ${String(err && err.message || err)}`));
      return json({ error: "internal error" }, 500);
    }
  },

  // Nightly housekeeping: expire old download links and synthetic test rows.
  async scheduled(event, env, ctx) {
    ctx.waitUntil(housekeeping(env));
  },
};

// ───────────────────────── helpers ─────────────────────────

function json(body, status = 200, extra = {}) {
  return new Response(JSON.stringify(body), { status, headers: { ...JSON_HEADERS, ...extra } });
}

function allowedOrigin(env, origin) {
  if (!origin) return null;
  const list = String(env.SITE_ORIGIN || "").split(",").map((s) => s.trim()).filter(Boolean);
  if (list.includes("*")) return "*";
  return list.includes(origin) ? origin : null;
}

function withCors(resp, env, origin) {
  const allow = allowedOrigin(env, origin);
  if (!allow) return resp;
  const r = new Response(resp.body, resp);
  r.headers.set("Access-Control-Allow-Origin", allow);
  r.headers.set("Vary", "Origin");
  return r;
}

function preflight(env, origin) {
  const allow = allowedOrigin(env, origin);
  if (!allow) return new Response(null, { status: 204 });
  return new Response(null, {
    status: 204,
    headers: {
      "Access-Control-Allow-Origin": allow,
      "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type",
      "Access-Control-Max-Age": "86400",
      Vary: "Origin",
    },
  });
}

const enc = new TextEncoder();

async function hmacKey(secret) {
  return crypto.subtle.importKey("raw", typeof secret === "string" ? enc.encode(secret) : secret, { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
}

async function hmacHex(secret, data) {
  const sig = await crypto.subtle.sign("HMAC", await hmacKey(secret), enc.encode(data));
  return [...new Uint8Array(sig)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

async function hmacBytes(secret, data) {
  return new Uint8Array(await crypto.subtle.sign("HMAC", await hmacKey(secret), enc.encode(data)));
}

function timingSafeEqual(a, b) {
  if (typeof a !== "string" || typeof b !== "string" || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

function b64url(bytes) {
  let s = "";
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function b64urlDecode(str) {
  const pad = str.length % 4 === 0 ? "" : "=".repeat(4 - (str.length % 4));
  const bin = atob(str.replace(/-/g, "+").replace(/_/g, "/") + pad);
  return Uint8Array.from(bin, (c) => c.charCodeAt(0));
}

function bearerOK(request, env) {
  const h = request.headers.get("Authorization") || "";
  const token = h.startsWith("Bearer ") ? h.slice(7) : "";
  return Boolean(env.BACKPLANE_PROBE_TOKEN) && timingSafeEqual(token, env.BACKPLANE_PROBE_TOKEN);
}

function escapeHtml(s) {
  return String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

function money(amount, currency) {
  try {
    return new Intl.NumberFormat("en-US", { style: "currency", currency: String(currency || "usd").toUpperCase() }).format((amount || 0) / 100);
  } catch {
    return `${((amount || 0) / 100).toFixed(2)} ${String(currency || "").toUpperCase()}`;
  }
}

// ───────────────────────── Supabase (PostgREST) ─────────────────────────

function sbHeaders(env, extra = {}) {
  const key = env.SUPABASE_SECRET_KEY || "";
  const h = { apikey: key, "Content-Type": "application/json", ...extra };
  // Legacy service_role keys are JWTs and are also sent as a bearer token.
  if (key.startsWith("eyJ")) h.Authorization = `Bearer ${key}`;
  return h;
}

async function sb(env, method, path, body, prefer) {
  const res = await fetch(`${env.SUPABASE_URL}/rest/v1/${path}`, {
    method,
    headers: sbHeaders(env, prefer ? { Prefer: prefer } : {}),
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  if (!res.ok) throw new Error(`Supabase ${method} ${path.split("?")[0]} → ${res.status}: ${text.slice(0, 300)}`);
  return text ? JSON.parse(text) : null;
}

async function logEvent(env, source, kind, message, ref = null, isProbe = false) {
  if (!env.SUPABASE_URL || !env.SUPABASE_SECRET_KEY) return;
  try {
    await sb(env, "POST", "bp_events", [{ source, kind, message: String(message).slice(0, 500), ref, is_probe: isProbe }], "return=minimal");
  } catch (e) {
    console.warn("bp_events write failed", String(e));
  }
}

// ───────────────────────── Stripe ─────────────────────────

function stripeForm(obj, prefix = "", out = new URLSearchParams()) {
  for (const [k, v] of Object.entries(obj)) {
    const key = prefix ? `${prefix}[${k}]` : k;
    if (v === undefined || v === null) continue;
    if (Array.isArray(v)) v.forEach((item, i) => (typeof item === "object" ? stripeForm(item, `${key}[${i}]`, out) : out.append(`${key}[]`, String(item))));
    else if (typeof v === "object") stripeForm(v, key, out);
    else out.append(key, String(v));
  }
  return out;
}

async function stripe(env, method, path, params) {
  const base = env.STRIPE_API_BASE || "https://api.stripe.com";
  const res = await fetch(`${base}${path}`, {
    method,
    headers: {
      Authorization: `Bearer ${env.STRIPE_SECRET_KEY}`,
      "Stripe-Version": STRIPE_VERSION,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: params ? stripeForm(params).toString() : undefined,
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(`Stripe ${path} → ${res.status}: ${data?.error?.message || "error"}`);
  return data;
}

// Verifies the Stripe-Signature header: HMAC-SHA256 over "t.payload" with a
// five-minute tolerance, exactly as Stripe's libraries do.
async function verifyStripe(payload, header, secret, toleranceSec = 300) {
  if (!header || !secret) return false;
  let t = null;
  const sigs = [];
  for (const part of header.split(",")) {
    const [k, v] = part.trim().split("=");
    if (k === "t") t = v;
    else if (k === "v1" && v) sigs.push(v);
  }
  if (!t || !sigs.length) return false;
  if (Math.abs(Date.now() / 1000 - Number(t)) > toleranceSec) return false;
  const expected = await hmacHex(secret, `${t}.${payload}`);
  return sigs.some((s) => timingSafeEqual(s, expected));
}

// ───────────────────────── catalog ─────────────────────────

// CATALOG: { currency, items: [{ key, name, billing, prices: { once|month|year: price id }, amounts: {…} }] }
function catalog(env) {
  try {
    const c = JSON.parse(env.CATALOG || "");
    if (c && Array.isArray(c.items)) return c;
  } catch {
    // fall through
  }
  // Configuration from before the catalog: a single PRICE_ID.
  if (env.PRICE_ID) return { currency: "usd", items: [{ key: "main", name: env.PRODUCT_NAME || "Product", billing: "once", prices: { once: env.PRICE_ID }, amounts: {} }] };
  return { currency: "usd", items: [] };
}

class OrderError extends Error {}

// Reads what the customer wants from JSON, a form post or the query string:
//   { "items": [{ "key": "candle", "quantity": 2 }], "interval": "month" }
//   /checkout?item=candle&quantity=2
// Anything else in the request (a price, an amount) is ignored.
async function readOrder(request, url) {
  let body = {};
  if (request.method === "POST") {
    const type = request.headers.get("Content-Type") || "";
    if (type.includes("application/json")) body = (await request.json().catch(() => ({}))) || {};
    else if (type.includes("form")) body = Object.fromEntries((await request.formData().catch(() => new FormData())).entries());
  }
  const src = { ...Object.fromEntries(url.searchParams.entries()), ...body };
  const lines = Array.isArray(src.items) ? src.items : src.item ? [{ key: src.item, quantity: src.quantity }] : [];
  return { lines, interval: src.interval ? String(src.interval) : "" };
}

// Maps requested items to catalog prices. Throws OrderError with a message
// that is safe to show the customer.
function priceLines(env, requested, interval) {
  const cat = catalog(env);
  if (!cat.items.length) throw new OrderError("Nothing is for sale yet.");
  const max = Math.max(1, Number(env.MAX_QUANTITY || 1));
  const cart = env.CART === "true";
  const lines = requested.length ? requested : [{ key: cat.items[0].key, quantity: 1 }];
  if (lines.length > (cart ? 20 : 1)) throw new OrderError(cart ? "Up to 20 different items per order." : "Choose one item.");
  const merged = new Map();
  for (const l of lines) {
    const key = String(l?.key ?? l?.item ?? "");
    const item = cat.items.find((i) => i.key === key);
    if (!item) throw new OrderError(`Unknown item "${key.slice(0, 40)}".`);
    const qty = l?.quantity === undefined || l?.quantity === null || l?.quantity === "" ? 1 : Number(l.quantity);
    const total = (merged.get(key)?.quantity || 0) + qty;
    if (!Number.isInteger(qty) || qty < 1 || total > max) throw new OrderError(max === 1 ? "Quantity must be 1." : `Quantity must be between 1 and ${max}.`);
    merged.set(key, { item, quantity: total });
  }
  const chosen = [...merged.values()];
  const iv = interval || chosen[0].item.billing || Object.keys(chosen[0].item.prices)[0];
  for (const c of chosen) {
    if (!c.item.prices?.[iv]) throw new OrderError(`"${c.item.name}" isn't sold ${iv === "once" ? "as a one-time purchase" : iv === "month" ? "monthly" : iv === "year" ? "yearly" : "that way"}.`);
  }
  const out = chosen.map((c) => ({ key: c.item.key, name: c.item.name, quantity: c.quantity, price: c.item.prices[iv], amount: c.item.amounts?.[iv] ?? null }));
  const summary = out.map((l) => (l.quantity > 1 ? `${l.name} × ${l.quantity}` : l.name)).join(", ");
  return { interval: iv, currency: cat.currency, lines: out, summary: summary.slice(0, 450), keys: out.map((l) => `${l.key}:${l.quantity}`).join(",").slice(0, 490) };
}

// Public list of what's for sale (no Stripe ids), for your site's menu or pricing table.
function publicCatalog(env) {
  const cat = catalog(env);
  const items = cat.items.map((i) => ({
    key: i.key, name: i.name, description: i.description || undefined, minutes: i.minutes || undefined, billing: i.billing,
    prices: Object.fromEntries(Object.entries(i.amounts || {}).map(([iv, a]) => [iv, { amount: a, display: money(a, cat.currency) }])),
  }));
  return json({ currency: cat.currency, items, cart: env.CART === "true", max_quantity: Math.max(1, Number(env.MAX_QUANTITY || 1)) }, 200, { "cache-control": "public, max-age=60" });
}

// The item lines recorded on a paid session ("candle:2,soap:1").
function linesFromMeta(env, meta) {
  const cat = catalog(env);
  return String(meta?.item_keys || "").split(",").filter(Boolean).map((part) => {
    const [key, q] = part.split(":");
    const item = cat.items.find((i) => i.key === key);
    return { key, name: item?.name || key, quantity: Number(q) || 1 };
  });
}

async function checkout(request, env, url) {
  const probe = request.headers.get("X-Backplane-Probe");
  const isProbe = Boolean(probe) && timingSafeEqual(probe, env.BACKPLANE_PROBE_TOKEN || "");
  const base = `${url.protocol}//${url.host}`;
  const shipping = env.FULFILLMENT_MODE === "shipping";
  let order;
  try {
    const req = await readOrder(request, url);
    order = priceLines(env, req.lines, req.interval);
  } catch (e) {
    if (e instanceof OrderError) return json({ error: e.message }, 400);
    throw e;
  }
  const subscription = order.interval !== "once";
  const session = await stripe(env, "POST", "/v1/checkout/sessions", {
    mode: subscription ? "subscription" : "payment",
    line_items: order.lines.map((l) => ({ price: l.price, quantity: l.quantity })),
    // Physical goods: Stripe collects and validates the delivery address.
    shipping_address_collection: shipping ? { allowed_countries: shipCountries(env) } : undefined,
    phone_number_collection: shipping ? { enabled: true } : undefined,
    success_url: (env.SUCCESS_URL || `${base}/thanks`) + (String(env.SUCCESS_URL || "").includes("?") ? "&" : "?") + "session_id={CHECKOUT_SESSION_ID}",
    cancel_url: env.CANCEL_URL || env.SITE_URL || base,
    customer_creation: subscription ? undefined : "always",
    allow_promotion_codes: env.ALLOW_PROMO_CODES === "true" ? true : undefined,
    metadata: { product: order.summary, items: order.summary, item_keys: order.keys, interval: order.interval, ...(isProbe ? { backplane_probe: "1" } : {}) },
  });
  const wantsJson = (request.headers.get("Accept") || "").includes("application/json") || isProbe;
  if (wantsJson) return json({ id: session.id, url: session.url });
  return Response.redirect(session.url, 303);
}

async function stripeWebhook(request, env, ctx, url) {
  const payload = await request.text();
  const ok = await verifyStripe(payload, request.headers.get("Stripe-Signature"), env.STRIPE_WEBHOOK_SECRET);
  if (!ok) return json({ error: "invalid signature" }, 400);
  const event = JSON.parse(payload);
  const obj = event.data?.object || {};
  const isProbe = event.livemode === false && obj.metadata?.backplane_probe === "1";

  // Delivery probe: Backplane expires a Checkout Session and waits for this.
  if (event.type === "checkout.session.expired") {
    if (obj.metadata?.backplane_probe === "1" && env.PROBES) {
      await env.PROBES.put(`probe:cs:${obj.id}`, JSON.stringify({ event_id: event.id, at: new Date().toISOString() }), { expirationTtl: 3600 });
    }
    return json({ received: true, type: event.type });
  }

  // Idempotency: Stripe retries deliveries, so every event is recorded once
  // and only marked processed after fulfilment fully succeeds.
  const inserted = await sb(env, "POST", "webhook_events?on_conflict=event_id",
    [{ event_id: event.id, type: event.type, livemode: Boolean(event.livemode) }], "resolution=ignore-duplicates,return=representation");
  if (!inserted || inserted.length === 0) {
    const prev = await sb(env, "GET", `webhook_events?event_id=eq.${encodeURIComponent(event.id)}&select=processed_at`);
    if (prev?.[0]?.processed_at) return json({ received: true, duplicate: true, type: event.type });
  }

  let result = { received: true, type: event.type };
  switch (event.type) {
    case "checkout.session.completed":
    case "checkout.session.async_payment_succeeded":
      result = { ...result, ...(await fulfil(obj, env, ctx, url, isProbe)) };
      break;
    case "charge.refunded":
      result = { ...result, ...(await refund(obj, env, ctx)) };
      break;
    case "customer.subscription.deleted":
      result = { ...result, ...(await subscriptionEnded(obj, env, ctx)) };
      break;
    default:
      break;
  }
  await sb(env, "PATCH", `webhook_events?event_id=eq.${encodeURIComponent(event.id)}`,
    { processed_at: new Date().toISOString(), outcome: result.outcome || "ok" }, "return=minimal");
  delete result.outcome;
  if (!isProbe) delete result.probe;
  return json(result);
}

function shipCountries(env) {
  const list = String(env.SHIP_COUNTRIES || "US").split(",").map((c) => c.trim().toUpperCase()).filter((c) => /^[A-Z]{2}$/.test(c));
  return list.length ? list : ["US"];
}

async function fulfil(session, env, ctx, url, isProbe) {
  if (session.payment_status !== "paid" && session.payment_status !== "no_payment_required") {
    // Delayed payment methods finish later with async_payment_succeeded.
    return { outcome: "awaiting_payment" };
  }
  if (env.FULFILLMENT_MODE === "shipping") return fulfilShipment(session, env, ctx, isProbe);
  const email = session.customer_details?.email || session.customer_email;
  if (!email) throw new Error("Checkout Session has no customer email");
  const orders = await sb(env, "POST", "orders?on_conflict=stripe_session_id", [{
    ...orderBasics(session, env, isProbe),
    email,
  }], "resolution=merge-duplicates,return=representation");
  const order = orders[0];
  const objectKey = isProbe && session.metadata?.backplane_probe_object ? session.metadata.backplane_probe_object : env.PRODUCT_FILE_KEY;
  const ttlHours = Number(env.DOWNLOAD_TTL_HOURS || 72);
  const expires = Math.floor(Date.now() / 1000) + ttlHours * 3600;
  await sb(env, "POST", "downloads?on_conflict=stripe_session_id,object_key", [{
    order_id: order.id, stripe_session_id: session.id, object_key: objectKey,
    expires_at: new Date(expires * 1000).toISOString(), max_downloads: Number(env.MAX_DOWNLOADS || 10),
  }], "resolution=merge-duplicates,return=minimal");
  const downloadUrl = await signedDownloadUrl(env, url, session.id, objectKey, expires);
  const license = env.LICENSE_MODE === "key" ? await issueLicense(env, order, session) : null;

  // Send the email once per order, even if Stripe retries the event.
  let emailId = null;
  let emailError = null;
  const sent = await sb(env, "GET", `email_log?stripe_session_id=eq.${encodeURIComponent(session.id)}&kind=eq.purchase&select=resend_email_id`);
  if (sent?.length) {
    emailId = sent[0].resend_email_id;
  } else {
    try {
      emailId = await sendPurchaseEmail(env, { email, name: session.customer_details?.name, order, downloadUrl, expires, license });
      await sb(env, "POST", "email_log", [{ resend_email_id: emailId, stripe_session_id: session.id, recipient: email, kind: "purchase" }], "return=minimal");
    } catch (e) {
      emailError = String(e.message || e);
      console.error("Purchase email failed", emailError);
    }
  }
  ctx.waitUntil((async () => {
    await logEvent(env, "stripe", "payment", `Payment completed ${money(order.amount_total, order.currency)}`, session.id, isProbe);
    await logEvent(env, "supabase", "order", `Order ${order.id} recorded`, session.id, isProbe);
    await logEvent(env, "r2", "download_link", `Signed download link issued (expires in ${ttlHours}h)`, session.id, isProbe);
    await logEvent(env, "resend", emailError ? "email_failed" : "email", emailError ? `Email failed: ${emailError}` : `Receipt email accepted (${emailId})`, session.id, isProbe);
  })());
  if (emailError && !isProbe) {
    // Fail the delivery so Stripe retries; the order and link are kept.
    throw new Error(`email failed: ${emailError}`);
  }
  return { outcome: "fulfilled", probe: { order_id: order.id, download_url: downloadUrl, email_id: emailId, email_error: emailError } };
}

// The columns every paid order records. What was bought comes from the
// session's metadata, which only this Worker writes.
function orderBasics(session, env, isProbe) {
  return {
    stripe_session_id: session.id,
    stripe_payment_intent: typeof session.payment_intent === "string" ? session.payment_intent : session.payment_intent?.id ?? null,
    stripe_subscription_id: typeof session.subscription === "string" ? session.subscription : session.subscription?.id ?? null,
    customer_name: session.customer_details?.name ?? null,
    product: session.metadata?.items || env.PRODUCT_NAME,
    items: linesFromMeta(env, session.metadata),
    amount_total: session.amount_total ?? 0,
    currency: session.currency ?? "usd",
    status: "paid",
    is_probe: isProbe,
  };
}

// Physical orders: record who and where to ship, confirm by email. Fulfilment
// status is updated from your own tools (or the Supabase dashboard).
async function fulfilShipment(session, env, ctx, isProbe) {
  const email = session.customer_details?.email || session.customer_email;
  if (!email) throw new Error("Checkout Session has no customer email");
  const ship = session.collected_information?.shipping_details || session.shipping_details || null;
  const orders = await sb(env, "POST", "orders?on_conflict=stripe_session_id", [{
    ...orderBasics(session, env, isProbe),
    email,
    shipping_name: ship?.name ?? session.customer_details?.name ?? null,
    shipping_address: ship?.address ?? null,
    phone: session.customer_details?.phone ?? null,
    fulfillment_status: "unfulfilled",
  }], "resolution=merge-duplicates,return=representation");
  const order = orders[0];
  let emailId = null;
  let emailError = null;
  const sent = await sb(env, "GET", `email_log?stripe_session_id=eq.${encodeURIComponent(session.id)}&kind=eq.purchase&select=resend_email_id`);
  if (sent?.length) {
    emailId = sent[0].resend_email_id;
  } else {
    try {
      emailId = await sendOrderEmail(env, { email, name: session.customer_details?.name, order, ship });
      await sb(env, "POST", "email_log", [{ resend_email_id: emailId, stripe_session_id: session.id, recipient: email, kind: "purchase" }], "return=minimal");
    } catch (e) {
      emailError = String(e.message || e);
      console.error("Order email failed", emailError);
    }
  }
  ctx.waitUntil((async () => {
    await logEvent(env, "stripe", "payment", `Payment completed ${money(order.amount_total, order.currency)}`, session.id, isProbe);
    await logEvent(env, "supabase", "order", `Order ${order.id} recorded for shipping`, session.id, isProbe);
    await logEvent(env, "resend", emailError ? "email_failed" : "email", emailError ? `Email failed: ${emailError}` : `Order confirmation accepted (${emailId})`, session.id, isProbe);
  })());
  if (emailError && !isProbe) throw new Error(`email failed: ${emailError}`);
  return { outcome: "fulfilled", probe: { order_id: order.id, email_id: emailId, email_error: emailError } };
}

async function sendOrderEmail(env, { email, name, order, ship }) {
  const a = ship?.address || {};
  const lines = [ship?.name, a.line1, a.line2, [a.postal_code, a.city].filter(Boolean).join(" "), a.state, a.country].filter(Boolean);
  const business = env.BUSINESS_NAME || env.PRODUCT_NAME;
  const msg = {
    from: env.FROM_EMAIL, to: [email], tags: [{ name: "kind", value: "purchase" }],
    subject: `Order confirmed — ${business}`,
    text: `Thanks for your order of ${order.product} (${money(order.amount_total, order.currency)}).\nWe'll ship to:\n${lines.join("\n")}\nOrder ${order.id}`,
    html: `<!doctype html><html><body style="margin:0;background:#f4f2ee;padding:32px 12px;font:16px/1.55 -apple-system,Segoe UI,Roboto,Arial,sans-serif;color:#1b1d1f">
<table role="presentation" width="100%" style="max-width:560px;margin:0 auto;background:#fff;border:1px solid #e3ded4;border-radius:10px"><tr><td style="padding:32px">
<p style="margin:0 0 6px;font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:#6b665c">${escapeHtml(business)}</p>
<h1 style="margin:0 0 16px;font-size:24px">Thanks, ${escapeHtml(name || "there")} — your order is confirmed.</h1>
<p style="margin:0 0 18px">You ordered <strong>${escapeHtml(order.product)}</strong> for ${escapeHtml(money(order.amount_total, order.currency))}. We'll email you when it ships.</p>
<p style="margin:0 0 6px;color:#555">Shipping to</p><p style="margin:0 0 22px">${lines.map(escapeHtml).join("<br>")}</p>
<hr style="border:0;border-top:1px solid #eee;margin:26px 0 14px"><p style="margin:0;color:#777;font-size:13px">Order ${escapeHtml(order.id)} · Questions? Reply or write to ${escapeHtml(env.SUPPORT_EMAIL || env.FROM_EMAIL)}.</p>
</td></tr></table></body></html>`,
  };
  if (env.SUPPORT_EMAIL) msg.reply_to = env.SUPPORT_EMAIL;
  const r = await resend(env, "/emails", msg);
  if (!r.ok) throw new Error(`Resend ${r.status}: ${r.data?.message || r.data?.name || "error"}`);
  return r.data.id;
}

async function refund(charge, env, ctx) {
  const pi = typeof charge.payment_intent === "string" ? charge.payment_intent : charge.payment_intent?.id;
  if (!pi || !charge.refunded) return { outcome: "partial_refund_ignored" };
  const orders = await sb(env, "PATCH", `orders?stripe_payment_intent=eq.${encodeURIComponent(pi)}`, { status: "refunded" }, "return=representation");
  for (const o of orders || []) {
    await sb(env, "PATCH", `downloads?order_id=eq.${o.id}`, { revoked: true }, "return=minimal");
  }
  ctx.waitUntil(logEvent(env, "stripe", "refund", `Refund processed; ${orders?.length || 0} order(s) revoked`, pi));
  return { outcome: "refunded" };
}

// A canceled subscription ends access: the order is marked canceled, and
// its downloads and license keys stop working.
async function subscriptionEnded(sub, env, ctx) {
  const orders = await sb(env, "PATCH", `orders?stripe_subscription_id=eq.${encodeURIComponent(sub.id)}&status=eq.paid`, { status: "canceled" }, "return=representation");
  for (const o of orders || []) {
    await sb(env, "PATCH", `downloads?order_id=eq.${o.id}`, { revoked: true }, "return=minimal");
    await sb(env, "PATCH", `licenses?order_id=eq.${o.id}`, { revoked: true }, "return=minimal");
  }
  ctx.waitUntil(logEvent(env, "stripe", "subscription", `Subscription ${sub.id} ended; ${orders?.length || 0} order(s) closed`, sub.id));
  return { outcome: "subscription_ended" };
}

// ───────────────────────── downloads ─────────────────────────

async function signedDownloadUrl(env, url, sessionId, key, expires) {
  const body = b64url(enc.encode(JSON.stringify({ s: sessionId, k: key, e: expires })));
  const sig = b64url(await hmacBytes(env.DOWNLOAD_SIGNING_SECRET, body));
  const base = env.PUBLIC_URL || `${url.protocol}//${url.host}`;
  return `${base}/download?t=${body}.${sig}`;
}

async function download(url, env, ctx) {
  const token = url.searchParams.get("t") || "";
  const [body, sig] = token.split(".");
  if (!body || !sig) return json({ error: "invalid link" }, 400);
  const expected = b64url(await hmacBytes(env.DOWNLOAD_SIGNING_SECRET, body));
  if (!timingSafeEqual(sig, expected)) return json({ error: "invalid link" }, 403);
  let claim;
  try {
    claim = JSON.parse(new TextDecoder().decode(b64urlDecode(body)));
  } catch {
    return json({ error: "invalid link" }, 400);
  }
  if (!claim.e || claim.e < Date.now() / 1000) return json({ error: "This download link has expired. Use the link in your latest email or contact support." }, 410);
  const rows = await sb(env, "GET", `downloads?stripe_session_id=eq.${encodeURIComponent(claim.s)}&object_key=eq.${encodeURIComponent(claim.k)}&select=revoked,download_count,max_downloads,orders(status)`);
  const row = rows?.[0];
  if (!row || row.revoked || row.orders?.status !== "paid") return json({ error: "This download is no longer available." }, 403);
  if (row.download_count >= row.max_downloads) return json({ error: "Download limit reached. Contact support for a new link." }, 429);
  const obj = await env.DOWNLOADS.get(claim.k);
  if (!obj) {
    console.error("Download object missing", claim.k);
    return json({ error: "File not found. The seller has been notified." }, 404);
  }
  ctx.waitUntil(sb(env, "POST", "rpc/bp_record_download", { p_session: claim.s, p_key: claim.k }).catch((e) => console.warn(String(e))));
  const filename = claim.k.split("/").pop();
  const headers = new Headers();
  obj.writeHttpMetadata(headers);
  headers.set("etag", obj.httpEtag);
  headers.set("content-disposition", `attachment; filename="${filename.replace(/"/g, "")}"`);
  headers.set("cache-control", "private, no-store");
  if (obj.size != null) headers.set("content-length", String(obj.size));
  return new Response(obj.body, { headers });
}

// ───────────────────────── licenses (optional) ─────────────────────────

async function licenseKeyFor(env, sessionId) {
  // Deterministic per order so a retried webhook issues the same key.
  const hex = (await hmacHex(env.DOWNLOAD_SIGNING_SECRET, `license:${sessionId}`)).toUpperCase();
  return [hex.slice(0, 5), hex.slice(5, 10), hex.slice(10, 15), hex.slice(15, 20)].join("-");
}

async function issueLicense(env, order, session) {
  const key = await licenseKeyFor(env, session.id);
  const hash = await hmacHex(env.DOWNLOAD_SIGNING_SECRET, `license-hash:${key}`);
  await sb(env, "POST", "licenses?on_conflict=key_hash", [{ order_id: order.id, key_hash: hash, key_hint: key.slice(-5), product: order.product || env.PRODUCT_NAME, is_probe: order.is_probe }],
    "resolution=ignore-duplicates,return=minimal");
  return key;
}

async function validateLicense(request, env) {
  const { key } = await request.json().catch(() => ({}));
  if (!key || typeof key !== "string") return json({ valid: false, reason: "missing key" }, 400);
  const hash = await hmacHex(env.DOWNLOAD_SIGNING_SECRET, `license-hash:${key.trim().toUpperCase()}`);
  const rows = await sb(env, "GET", `licenses?key_hash=eq.${hash}&select=revoked,product,orders(status)`);
  const row = rows?.[0];
  const valid = Boolean(row) && !row.revoked && row.orders?.status === "paid";
  return json({ valid, product: valid ? row.product : undefined });
}

// ───────────────────────── email ─────────────────────────

async function resend(env, path, body) {
  const base = env.RESEND_API_BASE || "https://api.resend.com";
  const res = await fetch(`${base}${path}`, {
    method: body ? "POST" : "GET",
    headers: { Authorization: `Bearer ${env.RESEND_API_KEY}`, "Content-Type": "application/json" },
    body: body ? JSON.stringify(body) : undefined,
  });
  const data = await res.json().catch(() => ({}));
  return { ok: res.ok, status: res.status, data };
}

async function sendPurchaseEmail(env, { email, name, order, downloadUrl, expires, license }) {
  const expiresText = new Date(expires * 1000).toUTCString().replace(" GMT", " UTC");
  const vars = {
    PRODUCT_NAME: order.product || env.PRODUCT_NAME, CUSTOMER_NAME: name || "there", DOWNLOAD_URL: downloadUrl, AMOUNT: money(order.amount_total, order.currency),
    ORDER_ID: order.id, EXPIRES: expiresText, BUSINESS_NAME: env.BUSINESS_NAME || env.PRODUCT_NAME, SUPPORT_EMAIL: env.SUPPORT_EMAIL || env.FROM_EMAIL,
    LICENSE_KEY: license || "",
  };
  const base = { from: env.FROM_EMAIL, to: [email], tags: [{ name: "kind", value: "purchase" }] };
  if (env.SUPPORT_EMAIL) base.reply_to = env.SUPPORT_EMAIL;
  const inline = {
    ...base,
    subject: `Your ${vars.PRODUCT_NAME} download`,
    html: purchaseHtml(vars),
    text: `Thanks for buying ${vars.PRODUCT_NAME} (${vars.AMOUNT}).\nDownload: ${vars.DOWNLOAD_URL}\nThe link works until ${vars.EXPIRES}.` + (license ? `\nLicense key: ${license}` : ""),
  };
  if (env.RESEND_TEMPLATE_PURCHASE) {
    const r = await resend(env, "/emails", { ...base, template: { id: env.RESEND_TEMPLATE_PURCHASE, variables: vars } });
    if (r.ok) return r.data.id;
    // A template edited into a broken state in the Resend dashboard must not
    // stop customers getting their download: fall back to the built-in email.
    if (r.status >= 500 || r.status === 429) throw new Error(`Resend ${r.status}: ${r.data?.message || "error"}`);
    console.warn("Template send failed, using built-in email", r.status, r.data?.message);
  }
  const r = await resend(env, "/emails", inline);
  if (!r.ok) throw new Error(`Resend ${r.status}: ${r.data?.message || r.data?.name || "error"}`);
  return r.data.id;
}

