// Resend delivery events (Svix-signed) update the email log.
async function resendWebhook(request, env, ctx) {
  const payload = await request.text();
  const id = request.headers.get("svix-id");
  const ts = request.headers.get("svix-timestamp");
  const sigHeader = request.headers.get("svix-signature") || "";
  if (!id || !ts || !env.RESEND_WEBHOOK_SECRET) return json({ error: "invalid signature" }, 400);
  if (Math.abs(Date.now() / 1000 - Number(ts)) > 300) return json({ error: "stale" }, 400);
  const secret = Uint8Array.from(atob(env.RESEND_WEBHOOK_SECRET.replace(/^whsec_/, "")), (c) => c.charCodeAt(0));
  const expected = btoa(String.fromCharCode(...(await hmacBytes(secret, `${id}.${ts}.${payload}`))));
  const ok = sigHeader.split(" ").some((p) => timingSafeEqual(p.split(",")[1] || "", expected));
  if (!ok) return json({ error: "invalid signature" }, 400);
  const evt = JSON.parse(payload);
  const emailId = evt.data?.email_id;
  if (emailId) {
    const status = String(evt.type || "").replace("email.", "");
    ctx.waitUntil(sb(env, "PATCH", `email_log?resend_email_id=eq.${encodeURIComponent(emailId)}`, { status, last_event_at: new Date().toISOString() }, "return=minimal")
      .then(() => (status === "bounced" || status === "complained") ? logEvent(env, "resend", status, `Email ${emailId} ${status}`, emailId) : null)
      .catch((e) => console.warn(String(e))));
  }
  return json({ received: true });
}

// Customers who lost or outlived their link can ask for fresh ones. The
// answer never reveals whether an email has orders, and each address is
// limited to one request per ten minutes.
async function resendLinks(request, env, ctx, url) {
  const { email } = await request.json().catch(() => ({}));
  if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(String(email))) return json({ error: "Enter the email you used at checkout." }, 400);
  const addr = String(email).trim().toLowerCase();
  const rlKey = `rl:links:${await hmacHex(env.DOWNLOAD_SIGNING_SECRET, addr)}`;
  if (env.PROBES && (await env.PROBES.get(rlKey))) return json({ sent: true });
  if (env.PROBES) await env.PROBES.put(rlKey, "1", { expirationTtl: 600 });
  ctx.waitUntil((async () => {
    const orders = await sb(env, "GET", `orders?email=ilike.${encodeURIComponent(addr)}&status=eq.paid&is_probe=eq.false&select=id,stripe_session_id,amount_total,currency,created_at&order=created_at.desc&limit=5`);
    if (!orders?.length) return;
    const ttlHours = Number(env.DOWNLOAD_TTL_HOURS || 72);
    const expires = Math.floor(Date.now() / 1000) + ttlHours * 3600;
    const links = [];
    for (const o of orders) {
      await sb(env, "PATCH", `downloads?stripe_session_id=eq.${encodeURIComponent(o.stripe_session_id)}&revoked=eq.false`, { expires_at: new Date(expires * 1000).toISOString() }, "return=minimal");
      links.push({ when: new Date(o.created_at).toDateString(), url: await signedDownloadUrl(env, url, o.stripe_session_id, env.PRODUCT_FILE_KEY, expires) });
    }
    const list = links.map((l) => `<li style="margin:0 0 10px"><a href="${escapeHtml(l.url)}">Download ${escapeHtml(env.PRODUCT_NAME)}</a> <span style="color:#777">(order from ${escapeHtml(l.when)})</span></li>`).join("");
    const r = await resend(env, "/emails", { from: env.FROM_EMAIL, to: [addr], subject: `Your ${env.PRODUCT_NAME} download links`,
      html: `<p>Here are fresh download links. They work for ${ttlHours} hours.</p><ul>${list}</ul>`, tags: [{ name: "kind", value: "links" }] });
    await logEvent(env, "resend", r.ok ? "email" : "email_failed", r.ok ? `Fresh download links emailed` : `Link email failed: ${r.data?.message || r.status}`);
  })().catch((e) => console.error("resendLinks", String(e))));
  return json({ sent: true });
}

// ───────────────────────── thank-you page ─────────────────────────

async function thanks(url, env) {
  const sid = url.searchParams.get("session_id") || "";
  let body = `<p>Your payment went through. Check your email for your download link — it usually arrives within a minute.</p>`;
  let refresh = "";
  if (/^cs_(test|live)_[A-Za-z0-9]+$/.test(sid)) {
    const rows = await sb(env, "GET", `orders?stripe_session_id=eq.${encodeURIComponent(sid)}&select=id,email,status`).catch(() => []);
    if (!rows?.length) {
      refresh = `<meta http-equiv="refresh" content="4">`;
      body = `<p>Finishing your order… this page refreshes automatically.</p>`;
    } else if (rows[0].status === "paid") {
      body = `<p>Thanks! We sent your download link to <strong>${escapeHtml(maskEmail(rows[0].email))}</strong>.</p><p>Didn't get it? Check spam, or contact ${escapeHtml(env.SUPPORT_EMAIL || env.FROM_EMAIL || "support")}.</p>`;
    }
  }
  const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">${refresh}<title>Thank you — ${escapeHtml(env.PRODUCT_NAME)}</title></head>
<body style="margin:0;min-height:100vh;display:grid;place-items:center;background:#f4f2ee;font:17px/1.6 -apple-system,Segoe UI,Roboto,Arial,sans-serif;color:#1b1d1f;padding:24px">
<main style="max-width:520px;background:#fff;border:1px solid #e3ded4;border-radius:10px;padding:32px"><h1 style="margin-top:0;font-size:26px">Thank you for buying ${escapeHtml(env.PRODUCT_NAME)}</h1>${body}</main></body></html>`;
  return new Response(html, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store", "x-content-type-options": "nosniff", "referrer-policy": "no-referrer" } });
}

function maskEmail(e) {
  const [u, d] = String(e).split("@");
  if (!d) return e;
  return `${u.slice(0, 2)}${"•".repeat(Math.max(1, u.length - 2))}@${d}`;
}

// ───────────────────────── Backplane probes ─────────────────────────

async function timed(fn) {
  const t0 = Date.now();
  try {
    const detail = await fn();
    return { ok: true, ms: Date.now() - t0, detail: detail || "" };
  } catch (e) {
    return { ok: false, ms: Date.now() - t0, error: String(e.message || e) };
  }
}

async function health(request, env, url) {
  if (!bearerOK(request, env)) return json({ error: "unauthorized" }, 401);
  const full = url.searchParams.get("mode") === "full";
  const missing = REQUIRED.filter((k) => !env[k]);
  if (!env.CATALOG && !env.PRICE_ID) missing.push("CATALOG");
  // Physical goods ship; only download stores have a file bucket.
  const downloads = env.FULFILLMENT_MODE !== "shipping";
  if (downloads && !env.DOWNLOADS) missing.push("DOWNLOADS (R2 binding)");
  if (!env.PROBES) missing.push("PROBES (KV binding)");
  const checks = {};
  if (downloads) checks.r2 = await timed(async () => {
    if (!env.DOWNLOADS) throw new Error("R2 binding DOWNLOADS is not bound");
    if (full) {
      const k = `__backplane/health-${crypto.randomUUID()}`;
      await env.DOWNLOADS.put(k, "ok");
      const got = await env.DOWNLOADS.get(k);
      if (!got || (await got.text()) !== "ok") throw new Error("read-back mismatch");
      await env.DOWNLOADS.delete(k);
    }
    const product = env.PRODUCT_FILE_KEY ? await env.DOWNLOADS.head(env.PRODUCT_FILE_KEY) : null;
    if (env.PRODUCT_FILE_KEY && !product) return `bucket reachable; product file ${env.PRODUCT_FILE_KEY} NOT uploaded yet`;
    return product ? `bucket reachable; product file present (${Math.round(product.size / 1024)} KB)` : "bucket reachable";
  });
  if (checks.r2?.ok && /NOT uploaded/.test(checks.r2.detail)) checks.r2 = { ...checks.r2, warn: true };
  checks.kv = await timed(async () => {
    if (!env.PROBES) throw new Error("KV binding PROBES is not bound");
    if (full) {
      const k = `bp:health:${crypto.randomUUID()}`;
      await env.PROBES.put(k, "ok", { expirationTtl: 60 });
      if ((await env.PROBES.get(k)) !== "ok") throw new Error("read-back mismatch");
      await env.PROBES.delete(k);
    } else {
      await env.PROBES.get("bp:health");
    }
    return "namespace reachable";
  });
  checks.supabase = await timed(async () => {
    if (!env.SUPABASE_URL || !env.SUPABASE_SECRET_KEY) throw new Error("SUPABASE_URL or SUPABASE_SECRET_KEY not set");
    await sb(env, "GET", "orders?select=id&limit=1");
    return "orders table reachable with the server key";
  });
  checks.stripe = await timed(async () => {
    if (!env.STRIPE_SECRET_KEY) throw new Error("STRIPE_SECRET_KEY not set");
    return await checkPrices(env);
  });
  checks.resend = await timed(async () => {
    if (!env.RESEND_API_KEY) throw new Error("RESEND_API_KEY not set");
    // A send-only key answers "restricted_api_key" on read endpoints: that
    // proves it is valid without sending anything.
    const r = await resend(env, "/domains");
    if (r.ok) return "key valid (full access — a send-only key is safer)";
    if (r.data?.name === "restricted_api_key") return "send-only key valid";
    throw new Error(`key rejected (${r.status} ${r.data?.name || ""})`);
  });
  const ok = missing.length === 0 && Object.values(checks).every((c) => c.ok);
  return json({ ok, worker: env.WORKER_NAME, version: env.CODE_VERSION || "", checks, missing, time: new Date().toISOString() }, 200, { "X-Backplane-Worker": env.WORKER_NAME || "" });
}

// Confirms the catalog's prices are active and readable with the Worker's key.
async function checkPrices(env) {
  const cat = catalog(env);
  if (!cat.items.length) throw new Error("nothing for sale: CATALOG has no items");
  const all = cat.items.flatMap((it) => Object.entries(it.prices || {}).map(([iv, id]) => ({ it, iv, id })));
  let mode = "test";
  for (const p of all.slice(0, HEALTH_PRICE_LIMIT)) {
    const price = await stripe(env, "GET", `/v1/prices/${encodeURIComponent(p.id)}`);
    if (!price.active) throw new Error(`price for ${p.it.name} (${p.iv}) is inactive`);
    mode = price.livemode ? "live" : "test";
  }
  return `${all.length} price${all.length === 1 ? "" : "s"} for ${cat.items.length} item${cat.items.length === 1 ? "" : "s"} active (${mode} mode)`;
}

async function probeStripe(request, env, sessionId) {
  if (!bearerOK(request, env)) return json({ error: "unauthorized" }, 401);
  const v = env.PROBES ? await env.PROBES.get(`probe:cs:${sessionId}`) : null;
  return json(v ? { found: true, ...JSON.parse(v) } : { found: false });
}

async function housekeeping(env) {
  const dayAgo = new Date(Date.now() - 86400_000).toISOString();
  try {
    await sb(env, "DELETE", `orders?is_probe=eq.true&created_at=lt.${dayAgo}`, undefined, "return=minimal");
    await sb(env, "DELETE", `backplane_probe?created_at=lt.${dayAgo}`, undefined, "return=minimal");
    await sb(env, "DELETE", `bp_events?is_probe=eq.true&at=lt.${dayAgo}`, undefined, "return=minimal");
  } catch (e) {
    console.error("housekeeping failed", String(e));
  }
}
